import { updateUrgencyPresetsSettings, type UrgencyPresetsConfig } from '~/client';

export const useUpdateSettingsUrgency = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: UrgencyPresetsConfig): Promise<UrgencyPresetsConfig> =>
      updateUrgencyPresetsSettings({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['system-settings'] });
      showToastSuccess('Urgency presets updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    updateSettingsUrgency: mutateAsync,
    isUpdateSettingsUrgencyLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
