<template>
  <Card>
    <CardHeader>
      <CardTitle>Urgency Presets</CardTitle>
    </CardHeader>
    <CardContent>
      <NavigationGuard
        :saved-data="processedPassedData"
        :changed-data="processedDataFromForm"
        title="Warning"
        description="You have some unsaved changes on this tab! Save them before switching to another tab."
        confirm-text="Discard Changes"
      />
      <form id="settingsUrgencyForm" class="flex flex-col gap-6" @submit="onSubmit">
        <div class="flex flex-col gap-4">
          <div
            v-for="level in urgencyLevels"
            :key="level"
            class="grid grid-cols-1 md:grid-cols-[120px_1fr_1fr] gap-4 items-end border-b pb-4"
          >
            <div class="flex items-end pb-1">
              <Badge :variant="campaignUrgencyConfig[level].variant">
                {{ campaignUrgencyConfig[level].label }}
              </Badge>
            </div>
            <FormItemWrapper
              label="Interval (hours)"
              :name="`${level}.interval_hours`"
              :is-required="true"
              :description="settingsFieldDescriptions.urgency.interval_hours"
            >
              <template #default="{ slots }">
                <Input :id="`${level}.interval_hours`" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
            <FormItemWrapper
              label="Daily Cap Per Campaign"
              :name="`${level}.daily_cap_per_campaign`"
              :is-required="true"
              :description="settingsFieldDescriptions.urgency.daily_cap_per_campaign"
            >
              <template #default="{ slots }">
                <Input :id="`${level}.daily_cap_per_campaign`" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
          </div>
        </div>

        <div class="flex justify-end">
          <Button
            type="submit"
            :loading="isUpdateSettingsUrgencyLoading"
            :disabled="isEqual(processedDataFromForm, processedPassedData) || isUpdateSettingsUrgencyLoading"
          >
            Save Urgency Presets
          </Button>
        </div>
      </form>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { isEqual } from 'lodash';
import type { CampaignUrgency, GetAllSystemSettingsResponse, UrgencyPresetsConfig } from '~/client';
import { formSchema } from '~/constants/validationSchemas/recruitmentSettingsUrgency';
import { useUpdateSettingsUrgency } from '~/mutations/system/updateSettingsUrgency';
import { campaignUrgencyConfig } from '~/constants/recruitment/campaignUrgencyConfig';
import { settingsFieldDescriptions } from '~/constants/recruitment/settingsFieldDescriptions';

const props = defineProps<{
  settings: GetAllSystemSettingsResponse;
}>();

definePageMeta({
  roles: ['admin'],
});

const { updateSettingsUrgency, isUpdateSettingsUrgencyLoading } = useUpdateSettingsUrgency();

const urgencyLevels = Object.keys(campaignUrgencyConfig) as CampaignUrgency[];

const { handleSubmit, values, resetForm } = useForm({
  validationSchema: formSchema,
  initialValues: {
    low: { interval_hours: undefined, daily_cap_per_campaign: undefined },
    normal: { interval_hours: undefined, daily_cap_per_campaign: undefined },
    elevated: { interval_hours: undefined, daily_cap_per_campaign: undefined },
    high: { interval_hours: undefined, daily_cap_per_campaign: undefined },
    critical: { interval_hours: undefined, daily_cap_per_campaign: undefined },
  },
});

function hydrate(config: UrgencyPresetsConfig) {
  resetForm({
    values: {
      low: { interval_hours: config.low.interval_hours, daily_cap_per_campaign: config.low.daily_cap_per_campaign },
      normal: {
        interval_hours: config.normal.interval_hours,
        daily_cap_per_campaign: config.normal.daily_cap_per_campaign,
      },
      elevated: {
        interval_hours: config.elevated.interval_hours,
        daily_cap_per_campaign: config.elevated.daily_cap_per_campaign,
      },
      high: { interval_hours: config.high.interval_hours, daily_cap_per_campaign: config.high.daily_cap_per_campaign },
      critical: {
        interval_hours: config.critical.interval_hours,
        daily_cap_per_campaign: config.critical.daily_cap_per_campaign,
      },
    },
  });
}

onMounted(() => hydrate(props.settings.urgency_presets));

const processedPassedData = computed(() => props.settings.urgency_presets);

const processedDataFromForm = computed(() => {
  const result = {} as UrgencyPresetsConfig;
  for (const level of urgencyLevels) {
    const nested = (values[level] ?? {}) as { interval_hours?: unknown; daily_cap_per_campaign?: unknown };
    result[level] = {
      interval_hours: toNumberOrNull(nested.interval_hours) ?? 0,
      daily_cap_per_campaign: toNumberOrNull(nested.daily_cap_per_campaign) ?? 0,
    };
  }
  return result;
});

const onSubmit = handleSubmit(async (formValues) => {
  await updateSettingsUrgency(formValues as UrgencyPresetsConfig);
  hydrate(formValues as UrgencyPresetsConfig);
});
</script>
