import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { positiveIntPreset } from './utils';

const urgencyPresetSchema = z.object({
  interval_hours: positiveIntPreset({
    max: 8760,
    requiredMessage: 'Interval is required',
    maxMessage: 'Must be at most 8760 (1 year)',
    integerMessage: 'Must be a whole number',
  }),
  daily_cap_per_campaign: positiveIntPreset({
    max: 5000,
    requiredMessage: 'Daily cap is required',
    maxMessage: 'Must be at most 5000',
    integerMessage: 'Must be a whole number',
  }),
});

export const schemaObject = {
  low: urgencyPresetSchema,
  normal: urgencyPresetSchema,
  elevated: urgencyPresetSchema,
  high: urgencyPresetSchema,
  critical: urgencyPresetSchema,
};

export const formSchema = toTypedSchema(z.object(schemaObject));
